def check_solution(a):
    sums = []
    n = len(a)
    for i in range(n):
        for j in range(i + 1, n):
            sums.append(a[i] + a[j])

    sums_set = set(sums)

    # Required set for n=4 is {1, 2, 3, 4, 5, 6}
    required_set = set(range(1, n * (n - 1) // 2 + 1))

    print(f"Input a: {a}")
    print(f"Calculated sums: {sorted(sums)}")
    print(f"Sums set matches required set: {sums_set == required_set}")

